class Solution {
public:
    int getShortestSequence(std::vector<int>& rolls, int k) {
        int ans = 1;
        std::unordered_set<int> seen;
        for (int x : rolls) {
            seen.insert(x);
            if ((int)seen.size() == k) {
                ans++;
                seen.clear();
            }
        }
        return ans;
    }
};

class Solution {
    public int getShortestSequence(int[] rolls, int k) {
        int ans = 1;
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        for (int x : rolls) {
            seen.add(x);
            if (seen.size() == k) {
                ans++;
                seen.clear();
            }
        }
        return ans;
    }
}

